def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    highchair_patches = image_patch.find("highchair")
    baby_patches = image_patch.find("baby")

    if not highchair_patches or not baby_patches:
        return image_patch

    baby_patch = baby_patches[0]
    highchair_patch = highchair_patches[0]

    baby_x, baby_y = baby_patch.horizontal_center, baby_patch.vertical_center
    highchair_x, highchair_y = highchair_patch.horizontal_center, highchair_patch.vertical_center

    if baby_x < highchair_x:
        return highchair_patch.crop(highchair_x - 20, highchair_y - 20, highchair_x + 20, highchair_y + 20)
    else:
        return highchair_patch.crop(highchair_x - 40, highchair_y - 40, highchair_x + 40, highchair_y + 40)

