def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    players = image_patch.find("baseball player")
    bats = image_patch.find("bat")
    balls = image_patch.find("baseball")

    if not players or not bats or not balls:
        return image_patch

    player_centers = [(p.left + p.right) / 2 for p in players]
    bat_centers = [(b.left + b.right) / 2 for b in bats]
    ball_centers = [(bl.left + bl.right) / 2 for bl in balls]

    for i, player_center in enumerate(player_centers):
        for j, bat_center in enumerate(bat_centers):
            for k, ball_center in enumerate(ball_centers):
                if abs(player_center - bat_center) < abs(player_center - ball_center):
                    continue
                if abs(bat_center - ball_center) < abs(player_center - ball_center):
                    continue
                return players[i]

    return image_patch

