def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    bowl_patches = image_patch.find("bowl")
    row_patches = image_patch.find("row")

    if not bowl_patches or not row_patches:
        return image_patch

    min_items = float('inf')
    edge_bowl = None

    for bowl in bowl_patches:
        items_in_row = 0
        for row in row_patches:
            if bowl.overlaps_with(row.left, row.lower, row.right, row.upper):
                items_in_row += 1
        if items_in_row < min_items:
            min_items = items_in_row
            edge_bowl = bowl

    return edge_bowl

