def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    bowls = image_patch.find("bowl")
    if not bowls: return image_patch

    rows = {}
    for bowl in bowls:
        x = bowl.horizontal_center
        if x not in rows:
            rows[x] = []
        rows[x].append(bowl)

    min_count_row = min(rows, key=lambda k: len(rows[k]))
    least_inside_bowls = rows[min_count_row]

    return least_inside_bowls[0]

